import { Field, ID, InterfaceType, ObjectType } from '@nestjs/graphql';

@InterfaceType()
export abstract class Character {
  @Field(() => ID)
  id: string;

  @Field()
  name: string;
}

@ObjectType({ implements: () => [Character] })
export class Human implements Character {
  id: string;
  name: string;

  @Field()
  age: number;
}

import {
  Args, Info, Parent, ResolveField, Resolver,
} from '@nestjs/graphql';

@Resolver(() => Character)
export class CharacterInterfaceResolver {
  @ResolveField(() => [Character])
  friends(
    @Parent() character: Character,
    @Info() { parentType },
    @Args('search', { type: () => String }) searchTerm: string,
  ) {
    return [];
  }
}

import { ObjectType, Field, Query } from '@nestjs/graphql';

@ObjectType()
export class Book {
  @Field()
  title: string;
}

@ObjectType()
export class Author {
  @Field()
  name: string;
}

export const ResultUnion = createUnionType({
  name: 'ResultUnion',
  types: () => [Author, Book] as const,
  resolveType(value) {
    return value.name ? Author : Book;
  },
});

import { registerEnumType } from '@nestjs/graphql';

export enum AllowedColor {
  RED,
  GREEN,
  BLUE,
}

registerEnumType(AllowedColor, {
  name: 'AllowedColor',
  description: 'The supported colors.',
  valuesMap: {
    RED: { description: 'The default color.' },
    BLUE: { deprecationReason: 'Too blue.' },
  },
});

import {
  FieldMiddleware,
  MiddlewareContext,
  NextFn,
} from '@nestjs/graphql';

const loggerMiddleware: FieldMiddleware = async (
  ctx: MiddlewareContext,
  next: NextFn,
) => {
  const value = await next();
  console.log(value);
  return value;
};

export { loggerMiddleware };

import { Field, ObjectType } from '@nestjs/graphql';
import { UseFieldMiddleware } from '@nestjs/graphql';

@ObjectType()
export class Recipe {
  @Field({ middleware: [loggerMiddleware] })
  title: string;

  @Field()
  @UseFieldMiddleware(loggerMiddleware)
  description: string;
}

@ResolveField(() => String, { middleware: [loggerMiddleware] })
title() {
  return 'Placeholder';
}

